/**
 * Release APKs per CPU architecture (docs/releasing.md).
 *
 * Phones run arm64-v8a, or armeabi-v7a on older and Android Go devices that ship a 32-bit system;
 * x86 and x86_64 are emulators and some Chromebooks, so release builds leave them out. Gradle then
 * writes one APK per architecture plus a universal fallback. Each gets its own version code,
 * `versionCode * 10 + n` (universal 0, armeabi-v7a 1, arm64-v8a 2), so any of them updates any
 * earlier release and a 64-bit phone moving off a 32-bit or universal install gets the higher code.
 * The android directory is regenerated by `expo prebuild`, hence a config plugin rather than an edit.
 */
const { withAppBuildGradle, withGradleProperties } = require("expo/config-plugins");

const ABIS = ["armeabi-v7a", "arm64-v8a"];
const MARKER = "// kolo: per-ABI APKs";

const SPLITS = `
${MARKER}
android {
    splits {
        abi {
            reset()
            enable true
            include ${ABIS.map(abi => `"${abi}"`).join(", ")}
            universalApk true
        }
    }
    // Prebuilt dependencies ship every architecture. React Native's own libraries are pickFirst
    // entries, which win over excludes, so the universal APK still carries their x86 builds (about 12 MB).
    packaging { jniLibs { excludes += ["**/x86/*.so", "**/x86_64/*.so"] } }
}
androidComponents {
    onVariants(selector().withBuildType("release")) { variant ->
        def offsets = [${ABIS.map((abi, index) => `"${abi}": ${index + 1}`).join(", ")}]
        variant.outputs.each { output ->
            def abi = output.filters.find { it.filterType.name() == "ABI" }?.identifier
            output.versionCode.set(output.versionCode.get() * 10 + (abi == null ? 0 : offsets[abi]))
        }
    }
}
`;

module.exports = function withAbiSplits(config) {
  config = withGradleProperties(config, config => {
    config.modResults = config.modResults.filter(item => !(item.type === "property" && item.key === "reactNativeArchitectures"));
    config.modResults.push({ type: "property", key: "reactNativeArchitectures", value: ABIS.join(",") });
    return config;
  });
  return withAppBuildGradle(config, config => {
    if (!config.modResults.contents.includes(MARKER)) config.modResults.contents += SPLITS;
    return config;
  });
};
